" stroke-width=\"1.2\"/><line x1=\"99.5\" y1=\"168.5\" x2=\"120.5\" y2=\"168.5\" class=\"s-gold\" stroke-width=\"1.2\"/><circle cx=\"110\" cy=\"88\" r=\"4\" class=\"f-gold\"/><path d=\"M100 82.0a10 10 0 0 0 0 12.0M120 82.0a10 10 0 0 1 0 12.0\" class=\"s-gold f-none\" stroke-width=\"1.5\"/><path d=\"M93 77.8a17 17 0 0 0 0 20.4M127 77.8a17 17 0 0 1 0 20.4\" class=\"s-gold f-none\" stroke-width=\"1.5\"/><path d=\"M68 132L94 116\" class=\"s-gold f-none\" stroke-width=\"1.5\" marker-end=\"url(#M3U1f1-m0)\" stroke-dasharray=\"3 3\"/><rect x=\"150\" y=\"112\" width=\"104\" height=\"72\" rx=\"6\" class=\"f-surface s-gold\" stroke-width=\"1.5\"/><rect x=\"160\" y=\"122\" width=\"84\" height=\"10\" rx=\"2\" class=\"f-muted\"/><circle cx=\"238\" cy=\"127\" r=\"2.5\" class=\"f-ok\"/><rect x=\"160\" y=\"138\" width=\"84\" height=\"10\" rx=\"2\" class=\"f-muted\"/><circle cx=\"238\" cy=\"143\" r=\"2.5\" class=\"f-ok\"/><rect x=\"160\" y=\"154\" width=\"84\" height=\"10\" rx=\"2\" class=\"f-muted\"/><circle cx=\"238\" cy=\"159\" r=\"2.5\" class=\"f-ok\"/><path d=\"M126 150L148 150\" class=\"s-gold f-none\" stroke-width=\"1.5\" marker-end=\"url(#M3U1f1-m0)\"/><path d=\"M254 170H268V270H452V176H464\" class=\"s-gold f-none\" stroke-width=\"4\"/><text x=\"360\" y=\"258\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"700\">fibre-optic cable</text><rect x=\"470\" y=\"112\" width=\"60\" height=\"72\" rx=\"6\" class=\"f-surface s-gold\" stroke-width=\"1.5\"/><rect x=\"478\" y=\"122\" width=\"44\" height=\"10\" rx=\"2\" class=\"f-muted\"/><rect x=\"478\" y=\"138\" width=\"44\" height=\"10\" rx=\"2\" class=\"f-muted\"/><rect x=\"478\" y=\"154\" width=\"44\" height=\"10\" rx=\"2\" class=\"f-muted\"/><path d=\"M517.4 86.6Q504.8 86.6 506.6 74Q508.4 61.4 522.8 63.2Q528.2 47 546.2 50.6Q562.4 43.4 571.4 61.4Q589.4 61.4 589.4 75.8Q589.4 86.6 576.8 86.6Z\" class=\"f-softb s-gold\" stroke-width=\"1.5\"/><path d=\"M512 108L528 90\" class=\"s-gold f-none\" stroke-width=\"1.5\" marker-end=\"url(#M3U1f1-m0)\"/><path d=\"M592 76L612 104\" class=\"s-gold f-none\" stroke-width=\"1.5\" marker-end=\"url(#M3U1f1-m0)\"/><rect x=\"598\" y=\"108\" width=\"24\" height=\"40\" rx=\"4\" class=\"f-surface s-gold\" stroke-width=\"1.5\"/><text x=\"610\" y=\"166\" font-size=\"13\" text-anchor=\"end\" class=\"f-muted\" font-weight=\"700\">Curaçao</text><text x=\"10\" y=\"312\" font-size=\"13\" class=\"f-gold\" font-weight=\"700\">Phone and tower</text><text x=\"10\" y=\"330\" font-size=\"13\"><tspan x=\"10\" dy=\"0em\">Radio network:</tspan><tspan x=\"10\" dy=\"1.2em\">towers, antennas</tspan><tspan x=\"10\" dy=\"1.2em\">and spectrum for</tspan><tspan x=\"10\" dy=\"1.2em\">4G LTE and 5G</tspan></text><text x=\"160\" y=\"312\" font-size=\"13\" class=\"f-gold\" font-weight=\"700\">Carrier's core</text><text x=\"160\" y=\"330\" font-size=\"13\"><tspan x=\"160\" dy=\"0em\">Routes calls, SMS</tspan><tspan x=\"160\" dy=\"1.2em\">and data; issues</tspan><tspan x=\"160\" dy=\"1.2em\">SIMs and numbers;</tspan><tspan x=\"160\" dy=\"1.2em\">bills</tspan></text><text x=\"310\" y=\"312\" font-size=\"13\" class=\"f-gold\" font-weight=\"700\">International link</text><text x=\"310\" y=\"330\" font-size=\"13\"><tspan x=\"310\" dy=\"0em\">Carriers buy</tspan><tspan x=\"310\" dy=\"1.2em\">capacity on</tspan><tspan x=\"310\" dy=\"1.2em\">submarine cables</tspan></text><text x=\"456\" y=\"312\" font-size=\"13\" class=\"f-gold\" font-weight=\"700\">App servers abroad</text><text x=\"456\" y=\"330\" font-size=\"13\"><tspan x=\"456\" dy=\"0em\">The voice note is</tspan><tspan x=\"456\" dy=\"1.2em\">passed on to the</tspan><tspan x=\"456\" dy=\"1.2em\">cousin's phone in</tspan><tspan x=\"456\" dy=\"1.2em\">Curaçao</tspan></text><rect x=\"10\" y=\"402\" width=\"620\" height=\"30\" rx=\"6\" class=\"f-surface s-line\" stroke-width=\"1\"/><text x=\"320\" y=\"422\" font-size=\"13\" text-anchor=\"middle\" class=\"f-muted\">Carriers also run roaming, prepaid and postpaid plans, zero-rating bundles and carrier billing.</text></svg>"
